class Npc { String id,faction,state; double food,rest,safety; Npc(this.id,this.faction,{this.state='idle',this.food=1,this.rest=1,this.safety=1}); }
class AaaSystems { int tick=0; final List<Npc> npcs=[]; final Map<String,double> prices={}; void tickOnce(){tick++;for(final n in npcs){n.food=(n.food-.005).clamp(0,1);n.rest=(n.rest-.003).clamp(0,1);n.state=n.safety<.25?'flee':n.food<.25?'seek_food':n.rest<.2?'sleep':'work';}} double market(String good,double supply,double demand){final p=((demand+1)/(supply+1)).clamp(.01,double.infinity);prices[good]=p;return p;} int resolveAbility(int base,int defense,int roll)=>roll+5<defense?0:base*(roll==20?2:1);}
